import re
import sympy
import numpy as np

def execute_python_code(code_str: str) -> str:
    """Executes code generated by the LLM in an isolated scope for math evaluation."""
    # Strip markdown formatting if the model wrapped output in backticks
    clean_code = re.sub(r"```python\s*|\s*```", "", code_str).strip()
    
    local_env = {}
    global_env = {
        "sympy": sympy,
        "np": np,
        "abs": abs,
        "max": max,
        "min": min,
        "sum": sum,
        "range": range
    }
    
    try:
        exec(clean_code, global_env, local_env)
        
        # We enforce assigning the final evaluation to 'result' in system prompt
        if "result" in local_env:
            return str(local_env["result"])
        
        return "Code ran successfully, but no 'result' variable was assigned."
        
    except Exception as err:
        # Pass the exact exception type back to the model so it can self-correct in the next turn
        return f"REPL Execution Error ({type(err).__name__}): {str(err)}"